// 此 gate 做蓝图级结构校验——确保高风险 Agent 的审批链在配置层面就位。
// ====================================================================
const HIGH_RISK_PATTERNS = [
    { pattern: /(?:修改|写入|创建|删除|覆盖).*(?:文件|代码|配置|数据库|仓库)/i, approvalLabel: 'file_modify', riskLevel: 'high' },
    { pattern: /(?:部署|发布|上线|release|deploy)/i, approvalLabel: 'deploy', riskLevel: 'critical' },
    { pattern: /(?:API|接口).*(?:调用|请求|修改)/i, approvalLabel: 'api_call', riskLevel: 'high' },
    { pattern: /(?:配置|config).*(?:变更|修改|更新)/i, approvalLabel: 'config_change', riskLevel: 'critical' },
    { pattern: /(?:删除|移除|清理).*(?:数据|用户|记录|账号)/i, approvalLabel: 'data_delete', riskLevel: 'critical' },
    { pattern: /(?:执行|运行).*(?:命令|脚本|command|script)/i, approvalLabel: 'command_exec', riskLevel: 'high' },
    { pattern: /(?:数据库|database|schema|migration).*(?:变更|修改|迁移)/i, approvalLabel: 'db_migrate', riskLevel: 'critical' },
    { pattern: /(?:支付|退款|交易|金额|finance)/i, approvalLabel: 'financial', riskLevel: 'critical' },
];
function checkSB07(blueprint) {
    const team = blueprint.teamStructure;
    const safetyBaseline = blueprint.collaborationMode.safetyBaseline;
    const issues = [];
    const highRiskAgents = [];
    const blockedLabels = new Set(safetyBaseline.requireHumanApproval || []);
    // 扫描所有角色的职责，检测高风险操作
    if (Array.isArray(team.roles)) {
        for (const role of team.roles) {
            const allText = `${role.name} ${role.responsibilities.join(' ')} ${(role.specialPrivileges || []).join(' ')}`;
            const matchedLabels = [];
            let maxRisk = 'high';
            for (const { pattern, approvalLabel, riskLevel } of HIGH_RISK_PATTERNS) {
                if (pattern.test(allText)) {
                    matchedLabels.push(approvalLabel);
                    if (riskLevel === 'critical')
                        maxRisk = 'critical';
                }
            }
            if (matchedLabels.length > 0) {
                highRiskAgents.push({ agentName: role.name, riskLabels: matchedLabels, riskLevel: maxRisk });
                // 检查审批链是否覆盖
                const uncovered = matchedLabels.filter(l => !blockedLabels.has(l));
                if (uncovered.length > 0) {
                    issues.push(`${role.name} 涉及高风险操作 [${uncovered.join(', ')}]，` +
                        `未在 safetyBaseline.requireHumanApproval 中注册`);
                }
            }
        }
    }
    // 检查 safetyBaseline.maxAutonomyLevel — 有高风险角色时不能为 'high'
    if (highRiskAgents.length > 0 && safetyBaseline.maxAutonomyLevel === 'high') {
        issues.push(`存在 ${highRiskAgents.length} 个高风险角色，` +
            `maxAutonomyLevel 不应为 'high'（当前：high）——建议降级为 'medium' 或 'low'`);
    }
    // 检查审批操作列表是否为空
    if (highRiskAgents.length > 0 && blockedLabels.size === 0) {
        issues.push(`蓝图包含高风险操作角色，但 requireHumanApproval 列表为空——` +
            `S-02 复述确认机制无法生效`);
    }
    if (issues.length > 0) {
        const criticalCount = highRiskAgents.filter(a => a.riskLevel === 'critical').length;
        const hasCritical = criticalCount > 0;
        return {
            ruleId: 'SB-07',
            ruleName: 'S-02 复述确认（高风险操作审批链）',
            passed: false,
            severity: hasCritical ? 'error' : 'warning',
            detail: issues.join('；'),
            blockReason: `高风险操作缺少审批注册: ${issues.join('; ')}`,
        };
    }
    if (highRiskAgents.length > 0) {
        return {
            ruleId: 'SB-07',
            ruleName: 'S-02 复述确认（高风险操作审批链）',
            passed: true,
            severity: 'info',
            detail: `${highRiskAgents.length} 个高风险角色均已在审批链中注册: [${highRiskAgents.map(a => a.agentName).join(', ')}]`,
        };
    }
    return {
        ruleId: 'SB-07',
        ruleName: 'S-02 复述确认（高风险操作审批链）',
        passed: true,
        severity: 'info',
        detail: '未检测到高风险操作角色，S-02 审批链校验通过',
    };
}
