/**
 * 对生成的 BlueprintDTO 执行安全基线硬阻断检查。
 * 应在 Blueprint 组装完成后、返回给用户前调用。
 */
function runSafetyGates(blueprint) {
    const rules = [
        checkSB01(blueprint),
        checkSB02(blueprint),
        checkSB03(blueprint),
        checkSB04(blueprint),
        checkSB05(blueprint),
        checkSB06(blueprint),
        checkSB07(blueprint),
    ];
    const blocked = rules.some(r => r.severity === 'error' && !r.passed);
    const passed = !blocked;
    const auditEntries = rules
        .filter(r => r.severity === 'error' || r.severity === 'warning')
        .map(r => `[${r.ruleId}] ${r.passed ? 'WARN' : 'BLOCKED'}: ${r.detail}`);
    const summary = blocked
        ? `安全基线阻断: ${rules.filter(r => !r.passed && r.severity === 'error').map(r => r.ruleId).join(', ')}`
        : `安全基线通过 (${rules.filter(r => r.passed).length}/${rules.length})`;
    return { passed, blocked, rules, summary, auditEntries };
}
